INSERT INTO courses(id,owner_id,title,description,start_date,end_date,status,student_ids,created_at,deleted_at) VALUES('f29c6d06-a469-4b76-8a23-99aba9e91415','2316c163-ca5b-49e3-94b2-8d0852576799','풀스택 웹 개발 기초','HTML·CSS·JavaScript로 화면을 구현하고, 서버 API와 PostgreSQL을 연결하여 회원가입·로그인 기능을 완성합니다. 주간 시험과 미니퀴즈로 이해도를 확인하고 부족한 개념을 보완합니다.','2026-11-16','2026-12-11','preparing','["9bd479c5-b6bd-45cb-a5f1-7a73cb4a9e1d","611ca32e-62a2-42c9-8adc-a0760d033208","b78f1e1a-6afa-4386-a070-94e25f165660","4b90093f-c128-4e45-8ba0-07bfa110d22b","5a200407-f603-4b04-b89b-e60034e4e9ad","612ad0d2-e27d-4e7d-b150-d5e08fd79efb","f0df9048-4128-4d60-b3d0-6fe2baaffd5d","be36465f-7ae2-4185-b7e3-63335a019fcc","24e630a5-95e3-4c0e-9faf-d7e787f7a618"]','2026-11-13T02:02:15.722Z',NULL);
INSERT INTO assessments(id,course_id,title,kind,week,duration,opens_at,closes_at,questions,created_at,published) VALUES('ad06a855-9a44-4dfa-aeda-43abfe37dd06','f29c6d06-a469-4b76-8a23-99aba9e91415','1주차 웹 기초 이해도 평가','exam',1,20,NULL,NULL,'[{"tag":"HTML 링크","answer":1,"points":10,"prompt":"HTML에서 다른 페이지로 이동하는 링크를 만드는 태그는?","options":["<p>","<a>","<div>","<span>"],"explanation":"<a>는 하이퍼링크를 만드는 태그이며, href 속성에 이동할 주소를 지정합니다."},{"tag":"HTML 폼","answer":0,"points":10,"prompt":"HTML에서 사용자의 입력을 받는 요소는?","options":["<input>","<h1>","<strong>","<footer>"],"explanation":"<input>은 텍스트·비밀번호 등 사용자 입력을 받는 요소입니다."},{"tag":"CSS 선택자","answer":2,"points":10,"prompt":"class=\"notice\"인 요소를 선택하는 CSS 선택자는?","options":["#notice","notice",".notice","*notice"],"explanation":"클래스 선택자는 클래스 이름 앞에 마침표(.)를 붙입니다."},{"tag":"CSS 글자 스타일","answer":3,"points":10,"prompt":"CSS에서 글자 색상을 지정하는 속성은?","options":["background","font-size","margin","color"],"explanation":"color는 글자 색상을 지정하는 속성입니다."},{"tag":"CSS 박스 모델","answer":1,"points":10,"prompt":"CSS에서 요소의 테두리 바깥 여백을 지정하는 속성은?","options":["padding","margin","border","width"],"explanation":"margin은 테두리 바깥 여백, padding은 테두리 안쪽 여백을 지정합니다."},{"tag":"JavaScript 변수","answer":2,"points":10,"prompt":"JavaScript에서 재할당할 수 없는 변수를 선언하는 키워드는?","options":["let","var","const","function"],"explanation":"const로 선언한 변수에는 다른 값을 재할당할 수 없습니다. 객체나 배열의 내부 내용은 변경할 수 있습니다."},{"tag":"JavaScript 자료형","answer":0,"points":10,"prompt":"typeof 123의 실행 결과는?","options":["\"number\"","\"string\"","\"boolean\"","\"object\""],"explanation":"숫자 값에 typeof를 적용하면 문자열 \"number\"가 반환됩니다."},{"tag":"JavaScript 함수","answer":3,"points":10,"prompt":"function add(a, b) { return a + b; }에서 add(2, 3)의 반환값은?","options":["2","3","\"23\"","5"],"explanation":"두 인수 2와 3을 더한 값 5를 반환합니다."},{"tag":"JavaScript 이벤트","answer":1,"points":10,"prompt":"버튼을 클릭했을 때 발생하는 이벤트 이름은?","options":["load","click","change","submit"],"explanation":"버튼 클릭은 click 이벤트로 처리합니다."},{"tag":"DOM 선택","answer":2,"points":10,"prompt":"document.querySelector(''#submitBtn'')이 선택하는 대상은?","options":["이름이 submitBtn인 태그","클래스가 submitBtn인 모든 요소","ID가 submitBtn인 첫 번째 요소","모든 버튼 요소"],"explanation":"#은 ID 선택자이며, querySelector()는 조건에 일치하는 첫 번째 요소를 반환합니다."}]','2026-11-13T02:02:15.722Z',0);
INSERT INTO assessments(id,course_id,title,kind,week,duration,opens_at,closes_at,questions,created_at,published) VALUES('f8cf20ce-2d01-4a7e-bc87-993d4a240918','f29c6d06-a469-4b76-8a23-99aba9e91415','웹 기초 서술형 평가','quiz',2,20,NULL,NULL,'[{"tag":"HTTP 요청·응답","type":"text","points":10,"prompt":"HTTP에서 요청과 응답이 어떤 역할을 하는지 클라이언트와 서버의 관계를 포함해 설명하세요.","rubric":"클라이언트가 요청을 보낸다는 설명 3점, 서버가 처리 후 응답한다는 설명 3점, 자원·작업 또는 상태 코드·데이터를 적절히 설명하면 4점. 표현이 달라도 의미가 정확하면 인정한다.","explanation":"요청과 응답의 주체 및 전달하는 정보를 구분한다.","model_answer":"클라이언트는 원하는 자원이나 작업을 HTTP 요청으로 서버에 전달한다. 서버는 요청을 처리한 후 상태 코드와 필요한 데이터를 HTTP 응답으로 반환한다."},{"tag":"웹 구성 요소","type":"text","points":10,"prompt":"HTML, CSS, JavaScript가 웹 화면에서 각각 담당하는 역할을 설명하세요.","rubric":"HTML의 구조·의미 3점, CSS의 표현·스타일 3점, JavaScript의 동작·상호작용 4점. 적절한 예시로 설명해도 인정한다.","explanation":"구조, 표현, 동작의 역할을 이해한다.","model_answer":"HTML은 문서의 구조와 의미를 정의하고, CSS는 색상·배치 등 표현을 담당한다. JavaScript는 사용자 입력에 반응하거나 데이터를 처리하는 동작을 구현한다."},{"tag":"인증·비밀번호 보관","type":"text","points":10,"prompt":"사용자의 비밀번호를 데이터베이스에 평문으로 저장하면 안 되는 이유와 적절한 저장 방법을 설명하세요.","rubric":"유출 시 비밀번호 노출 위험 4점, 비밀번호 저장용 해시 사용 4점, salt의 역할 또는 해시 비교를 통한 검증 설명 2점. 단순 암호화만 제시하면 해시 항목 점수는 부여하지 않는다.","explanation":"비밀번호 원문을 복원할 필요 없이 일치 여부를 검증하도록 설계한다.","model_answer":"평문으로 저장하면 데이터베이스 유출 시 비밀번호가 그대로 노출된다. 사용자별 salt와 비밀번호 저장용 해시 함수를 사용해 해시값을 저장하고 로그인 때 입력 비밀번호를 같은 방식으로 검증한다."}]','2026-11-13T02:02:15.759Z',0);
INSERT INTO assessments(id,course_id,title,kind,week,duration,opens_at,closes_at,questions,created_at,published) VALUES('9aa97137-bc25-4b1e-bc2e-6b520dd08772','f29c6d06-a469-4b76-8a23-99aba9e91415','웹 서비스 구조와 인증 이해도 평가','exam',2,30,NULL,NULL,'[{"tag":"HTML 링크","type":"choice","answer":1,"points":15,"prompt":"HTML에서 다른 페이지로 연결하는 링크를 만드는 요소는 무엇인가요?","options":["<p>","<a>","<div>","<span>"],"explanation":"a 요소의 href 속성에 연결할 주소를 지정합니다."},{"tag":"CSS 속성","type":"choice","answer":2,"points":15,"prompt":"CSS에서 글자 색상을 지정하는 속성은 무엇인가요?","options":["margin","display","color","padding"],"explanation":"color는 글자 색상, margin과 padding은 여백, display는 표시 방식을 지정합니다."},{"tag":"JavaScript 선언","type":"choice","answer":0,"points":15,"prompt":"JavaScript에서 재할당할 수 없는 변수를 선언하는 키워드는 무엇인가요?","options":["const","let","var","return"],"explanation":"const로 선언한 변수는 재할당할 수 없습니다. 객체의 내부 속성 변경 여부와는 구분합니다."},{"tag":"HTTP 상태 코드","type":"choice","answer":3,"points":15,"prompt":"HTTP 요청이 정상적으로 처리되었음을 나타내는 대표적인 상태 코드는 무엇인가요?","options":["404","500","401","200"],"explanation":"200은 성공, 401은 인증 필요, 404는 자원 없음, 500은 서버 오류를 나타냅니다."},{"tag":"웹 구조·인증 보안","type":"text","points":40,"prompt":"웹 서비스의 동작과 보안을 설명하세요. ① HTTP 요청·응답에서 클라이언트와 서버의 역할 ② HTML·CSS·JavaScript의 역할 ③ 비밀번호를 평문으로 저장하면 안 되는 이유와 적절한 저장 방법을 포함하세요.","rubric":"총 40점. 클라이언트 요청·서버 응답 역할 10점(각 5점). HTML 구조·CSS 표현·JavaScript 동작 15점(각 5점). 평문 유출 위험 5점. 비밀번호 해시 저장 7점과 salt 또는 안전한 비밀번호 해시 함수 예시 3점. 단순 암호화만 언급하면 해시 점수는 부여하지 않는다. 동등한 의미의 표현을 인정하고 누락·잘못된 설명에 대해서만 감점한다.","explanation":"웹 요청 처리, 화면 구성 요소의 역할, 안전한 비밀번호 보관을 함께 이해하는 문제입니다.","model_answer":"클라이언트는 HTTP 요청으로 자원이나 처리를 요청하고 서버는 처리 결과를 상태 코드와 데이터로 응답한다. HTML은 구조와 의미, CSS는 표현과 배치, JavaScript는 동작과 상호작용을 담당한다. 비밀번호를 평문으로 저장하면 유출 시 원문이 노출되므로 사용자별 salt와 비밀번호 저장용 해시 함수를 이용해 저장하고 입력값을 검증한다."}]','2026-11-13T02:02:15.763Z',1);
INSERT INTO assessment_results(id,assessment_id,student_id,questions,answers,score,total,submitted_at,duration_seconds,origin,grading,grading_status,revision) VALUES('b4dec263-6c57-bac3-7104-dd81c4786bd4','ad06a855-9a44-4dfa-aeda-43abfe37dd06','9bd479c5-b6bd-45cb-a5f1-7a73cb4a9e1d','[{"tag":"HTML 링크","answer":1,"points":10,"prompt":"HTML에서 다른 페이지로 이동하는 링크를 만드는 태그는?","options":["<p>","<a>","<div>","<span>"],"explanation":"<a>는 하이퍼링크를 만드는 태그이며, href 속성에 이동할 주소를 지정합니다."},{"tag":"HTML 폼","answer":0,"points":10,"prompt":"HTML에서 사용자의 입력을 받는 요소는?","options":["<input>","<h1>","<strong>","<footer>"],"explanation":"<input>은 텍스트·비밀번호 등 사용자 입력을 받는 요소입니다."},{"tag":"CSS 선택자","answer":2,"points":10,"prompt":"class=\"notice\"인 요소를 선택하는 CSS 선택자는?","options":["#notice","notice",".notice","*notice"],"explanation":"클래스 선택자는 클래스 이름 앞에 마침표(.)를 붙입니다."},{"tag":"CSS 글자 스타일","answer":3,"points":10,"prompt":"CSS에서 글자 색상을 지정하는 속성은?","options":["background","font-size","margin","color"],"explanation":"color는 글자 색상을 지정하는 속성입니다."},{"tag":"CSS 박스 모델","answer":1,"points":10,"prompt":"CSS에서 요소의 테두리 바깥 여백을 지정하는 속성은?","options":["padding","margin","border","width"],"explanation":"margin은 테두리 바깥 여백, padding은 테두리 안쪽 여백을 지정합니다."},{"tag":"JavaScript 변수","answer":2,"points":10,"prompt":"JavaScript에서 재할당할 수 없는 변수를 선언하는 키워드는?","options":["let","var","const","function"],"explanation":"const로 선언한 변수에는 다른 값을 재할당할 수 없습니다. 객체나 배열의 내부 내용은 변경할 수 있습니다."},{"tag":"JavaScript 자료형","answer":0,"points":10,"prompt":"typeof 123의 실행 결과는?","options":["\"number\"","\"string\"","\"boolean\"","\"object\""],"explanation":"숫자 값에 typeof를 적용하면 문자열 \"number\"가 반환됩니다."},{"tag":"JavaScript 함수","answer":3,"points":10,"prompt":"function add(a, b) { return a + b; }에서 add(2, 3)의 반환값은?","options":["2","3","\"23\"","5"],"explanation":"두 인수 2와 3을 더한 값 5를 반환합니다."},{"tag":"JavaScript 이벤트","answer":1,"points":10,"prompt":"버튼을 클릭했을 때 발생하는 이벤트 이름은?","options":["load","click","change","submit"],"explanation":"버튼 클릭은 click 이벤트로 처리합니다."},{"tag":"DOM 선택","answer":2,"points":10,"prompt":"document.querySelector(''#submitBtn'')이 선택하는 대상은?","options":["이름이 submitBtn인 태그","클래스가 submitBtn인 모든 요소","ID가 submitBtn인 첫 번째 요소","모든 버튼 요소"],"explanation":"#은 ID 선택자이며, querySelector()는 조건에 일치하는 첫 번째 요소를 반환합니다."}]','[1,0,2,3,1,2,0,3,1,2]',100,100,'2026-11-13T02:02:15.733Z',600,'generated','[]','confirmed',0);
