INSERT INTO assessment_results(id,assessment_id,student_id,questions,answers,score,total,submitted_at,duration_seconds,origin,grading,grading_status,revision) VALUES('0d576817-5ae5-203c-8271-3424d745563c','9aa97137-bc25-4b1e-bc2e-6b520dd08772','9bd479c5-b6bd-45cb-a5f1-7a73cb4a9e1d','[{"tag":"HTML 링크","type":"choice","answer":1,"points":15,"prompt":"HTML에서 다른 페이지로 연결하는 링크를 만드는 요소는 무엇인가요?","options":["<p>","<a>","<div>","<span>"],"explanation":"a 요소의 href 속성에 연결할 주소를 지정합니다."},{"tag":"CSS 속성","type":"choice","answer":2,"points":15,"prompt":"CSS에서 글자 색상을 지정하는 속성은 무엇인가요?","options":["margin","display","color","padding"],"explanation":"color는 글자 색상, margin과 padding은 여백, display는 표시 방식을 지정합니다."},{"tag":"JavaScript 선언","type":"choice","answer":0,"points":15,"prompt":"JavaScript에서 재할당할 수 없는 변수를 선언하는 키워드는 무엇인가요?","options":["const","let","var","return"],"explanation":"const로 선언한 변수는 재할당할 수 없습니다. 객체의 내부 속성 변경 여부와는 구분합니다."},{"tag":"HTTP 상태 코드","type":"choice","answer":3,"points":15,"prompt":"HTTP 요청이 정상적으로 처리되었음을 나타내는 대표적인 상태 코드는 무엇인가요?","options":["404","500","401","200"],"explanation":"200은 성공, 401은 인증 필요, 404는 자원 없음, 500은 서버 오류를 나타냅니다."},{"tag":"웹 구조·인증 보안","type":"text","points":40,"prompt":"웹 서비스의 동작과 보안을 설명하세요. ① HTTP 요청·응답에서 클라이언트와 서버의 역할 ② HTML·CSS·JavaScript의 역할 ③ 비밀번호를 평문으로 저장하면 안 되는 이유와 적절한 저장 방법을 포함하세요.","rubric":"총 40점. 클라이언트 요청·서버 응답 역할 10점(각 5점). HTML 구조·CSS 표현·JavaScript 동작 15점(각 5점). 평문 유출 위험 5점. 비밀번호 해시 저장 7점과 salt 또는 안전한 비밀번호 해시 함수 예시 3점. 단순 암호화만 언급하면 해시 점수는 부여하지 않는다. 동등한 의미의 표현을 인정하고 누락·잘못된 설명에 대해서만 감점한다.","explanation":"웹 요청 처리, 화면 구성 요소의 역할, 안전한 비밀번호 보관을 함께 이해하는 문제입니다.","model_answer":"클라이언트는 HTTP 요청으로 자원이나 처리를 요청하고 서버는 처리 결과를 상태 코드와 데이터로 응답한다. HTML은 구조와 의미, CSS는 표현과 배치, JavaScript는 동작과 상호작용을 담당한다. 비밀번호를 평문으로 저장하면 유출 시 원문이 노출되므로 사용자별 salt와 비밀번호 저장용 해시 함수를 이용해 저장하고 입력값을 검증한다."}]','[1,2,0,3,"클라이언트는 HTTP 요청으로 서버에 자원이나 처리를 요청한다. 서버는 요청을 처리하고 상태 코드와 데이터를 응답한다. HTML은 구조, CSS는 표현, JavaScript는 동작을 담당한다. 비밀번호는 유출에 대비해 사용자별 salt와 비밀번호 해시 함수를 적용해 저장하고 로그인 시 검증한다."]',60,100,'2026-11-13T02:02:15.763Z',720,'generated','[{"score":15,"status":"confirmed"},{"score":15,"status":"confirmed"},{"score":15,"status":"confirmed"},{"score":15,"status":"confirmed"},{"status":"pending"}]','pending',0);
